  "inlineSchema": "generator client {\n  provider = \"prisma-client-js\"\n  output   = \"../../prisma-client/generated/central\"\n}\n\ndatasource db {\n  provider = \"sqlite\"\n  url      = env(\"CENTRAL_DATABASE_URL\")\n}\n\n// ✅ Copy all models from Postgres schema here\nmodel SuperAdmin {\n  id          String   @id @default(uuid())\n  name        String\n  email       String   @unique\n  password    String\n  contact     String?\n  position    String\n  country     String?\n  state       String?\n  city        String?\n  zipCode     String?\n  fullAddress String?\n  createdAt   DateTime @default(now())\n\n  currentSessionToken String?\n  lastLoginAt         DateTime?\n\n  role Role @default(MASTER_ADMIN)\n\n  // 🆕 ADD THESE (MUST MATCH POSTGRES)\n  basicComplete   Boolean @default(false)\n  addressComplete Boolean @default(false)\n}\n\nmodel Tenant {\n  id                String   @id @default(uuid())\n  name              String\n  contact           String\n  fullAddress       String\n  logo              String?\n  certificateName   String?\n  stamp             String?\n  sign              String?\n  position          String\n  country           String\n  state             String\n  city              String\n  zipCode           String\n  instituteName     String   @unique\n  tenantId          String   @unique\n  slug              String   @unique\n  email             String?  @unique\n  businessEmail     String?\n  password          String?\n  encryptedPassword String\n  dbUrl             String\n  parentTenantId    String? // set when this tenant is a company under a master institute\n  loginCode         String?  @unique // short institute code staff type after @ when signing in, e.g. google@2026\n  createdAt         DateTime @default(now())\n}\n\nenum Role {\n  MASTER_ADMIN\n}\n\n// Subscription price list, managed by the master admin on the web portal.\nmodel SubscriptionPlan {\n  id        String   @id @default(uuid())\n  code      String   @unique // SIX_MONTH | ONE_YEAR\n  name      String\n  months    Int\n  price     Float\n  currency  String   @default(\"INR\")\n  active    Boolean  @default(true)\n  updatedAt DateTime @updatedAt\n}\n\n// One subscription per institute, written by the web portal after payment.\nmodel PortalSubscription {\n  id            String   @id @default(uuid())\n  email         String   @unique // tenant login email\n  clientId      String // tenant.tenantId\n  plan          String   @default(\"NONE\")\n  startDate     DateTime @default(now())\n  expiryDate    DateTime @default(now())\n  status        String   @default(\"EXPIRED\") // ACTIVE | EXPIRED | SUSPENDED | REVOKED\n  syncTokenHash String?\n  maxUsers      Int      @default(1) // max simultaneous logins bought\n  updatedAt     DateTime @updatedAt\n}\n\nmodel PortalPayment {\n  id        String   @id @default(uuid())\n  email     String\n  planCode  String\n  amount    Float\n  currency  String   @default(\"INR\")\n  maxUsers  Int      @default(1)\n  orderId   String   @unique\n  paymentId String?  @unique\n  status    String   @default(\"CREATED\") // CREATED | PAID | FAILED\n  createdAt DateTime @default(now())\n}\n\n// SaaS owner account for the hosted portal (/saas/login). Separate from the\n// per-install MASTER_ADMIN used inside the EXE.\nmodel SaasAdmin {\n  id        String   @id @default(uuid())\n  name      String\n  email     String   @unique\n  password  String\n  createdAt DateTime @default(now())\n}\n\n// Global settings shared by every EXE client (key -> JSON string).\nmodel AppSetting {\n  key       String   @id\n  value     String\n  updatedAt DateTime @updatedAt\n}\n\n// ---- EXE activation keys & device tracking (hosted portal) ----\n// One key belongs to one institute + company and allows `maxActivations` PCs.\nmodel ActivationKey {\n  id               String             @id @default(uuid())\n  key              String             @unique // VCIN-XXXX-XXXX-XXXX-XXXX\n  tenantId         String // master institute Tenant.id\n  instituteName    String\n  companyName      String\n  maxActivations   Int                @default(1)\n  transferLimit    Int                @default(3) // how many times a PC may be deactivated/replaced\n  transfersUsed    Int                @default(0)\n  status           String             @default(\"ACTIVE\") // ACTIVE | REVOKED\n  firstActivatedAt DateTime?\n  createdAt        DateTime           @default(now())\n  // One company has exactly two keys: SERVER (1 PC, the local server) and CLIENT (unlimited client PCs).\n  companyId        String? // ClientAdmin.id inside the institute database\n  kind             String             @default(\"SERVER\") // SERVER | CLIENT\n  devices          ActivationDevice[]\n\n  @@unique([tenantId, companyId, kind])\n}\n\nmodel ActivationDevice {\n  id              String        @id @default(uuid())\n  activationKeyId String\n  deviceId        String\n  deviceName      String\n  os              String        @default(\"\")\n  status          String        @default(\"ACTIVE\") // ACTIVE | INACTIVE\n  activatedAt     DateTime      @default(now())\n  lastVerifiedAt  DateTime      @default(now())\n  deactivatedAt   DateTime?\n  activationKey   ActivationKey @relation(fields: [activationKeyId], references: [id], onDelete: Cascade)\n\n  @@unique([activationKeyId, deviceId])\n}\n\n// ---- Local server only: client PCs (laptops / desktops) that confirmed the company's Client key ----\nmodel ClientDevice {\n  id          String   @id @default(uuid())\n  deviceId    String   @unique\n  deviceName  String\n  os          String   @default(\"\")\n  tokenHash   String\n  status      String   @default(\"ACTIVE\") // ACTIVE | REVOKED\n  confirmedAt DateTime @default(now())\n  lastSeenAt  DateTime @default(now())\n  lastIp      String?\n}\n",
